import{_ as t,o as e,c as l,a0 as s}from"./chunks/framework.DqMqoJl9.js";const C=JSON.parse('{"title":"Date.UTC()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Date/UTC.md","filePath":"jsApi/Date/UTC.md","lastUpdated":1791573371000}'),n={name:"jsApi/Date/UTC.md"};function o(r,a,i,p,d,c){return e(),l("div",null,[...a[0]||(a[0]=[s('<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Date/UTC" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Date/UTC" target="_blank">en</a></p><h1 id="date-utc" tabindex="-1">Date.UTC() <a class="header-anchor" href="#date-utc" aria-label="Permalink to &quot;Date.UTC()&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>Date.UTC() 方法接受的参数同日期构造函数接受最多参数时一样，返回从1970-1-1 00:00:00 UTC到指定日期的的毫秒数。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">UTC</span><span style="color:#24292E;">(year,month[,date[,hrs[,min[,sec[,ms]]]]])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>year</code> 1900 年后的某一年份</li><li><code>month</code> 0 到 11 之间的一个整数，表示月份</li><li><code>date</code> 1 到 31 之间的一个整数，表示某月当中的第几天</li><li><code>hrs</code> 0 到 23 之间的一个整数，表示小时</li><li><code>min</code> 0 到 59 之间的一个整数，表示分钟</li><li><code>sec</code> 0 到 59 之间的一个整数，表示秒</li><li><code>ms</code> 0 到 999 之间的一个整数，表示毫秒</li></ul><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>UTC 方法接受以逗号隔开的日期参数，返回1970-1-1 00:00:00 UTC到指定的日期之间的毫秒数。</p><p>你应该指定一个完整格式的年份，如 1998。如果年份被指定为 0 到 99 之间，则该方法会将年份转换为 20 世纪的一个年份（即 1990 + year），例如，指定为 95， 则年份为 1995。</p><p>UTC 方法与 Date 有两点不同：</p><ul><li>Date.UTC 方法使用协调世界时代替本地时间。</li><li>Date.UTC 方法返回一个时间数值，而不是一个日期对象。</li></ul><p>如果有一个指定的参数超出其合理范围，则 UTC 方法会通过更新其他参数直到该参数在合理范围内。例如，为月份指定 15，则年份将会加 1，然后月份将会使用 3。</p><p>由于 UTC 是 Date（日期对象）的一个静态方法，所以应该在 Date 上直接调用，就像 Date.UTC()，而不要把它作为创建的日期对象的方法。</p><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><p>下面的语句使用 UTC 时间代替本地时间创建了一个日期对象。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> utcDate </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(Date.</span><span style="color:#6F42C1;">UTC</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">96</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">11</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">));</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>',20)])])}const y=t(n,[["render",o]]);export{C as __pageData,y as default};
